"""Writes reports/M2E_VISUALIZATION_CATALOG.md from the figure manifests (no hand-typed counts)."""
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); PE = os.path.dirname(HERE); sys.path.insert(0, os.path.join(PE, 'python'))
from pe import forensics as F
FIG = os.path.join(PE, 'reports', 'm2e_figures'); K = [F.cycle_key(*c) for c in F.CYCLES]
M = {k: {f['figure']: f for f in json.load(open(os.path.join(FIG, k, 'figure_manifest.json')))['figures']} for k in K}
CM = {k: json.load(open(os.path.join(FIG, k, 'case_figure_manifest.json')))['figures'] for k in K}
DESC = [('V1_inventory_evolution', 'V1 Inventory evolution', 'Short/long CE/PE units, net and gross, after every fill; D-1 and D0 panels with the carried inventory annotated; cumulative opened/closed units (by MODULE-TAG class).', 'OBSERVED (fills + M2-B lifecycle). Role classes are tag labels, not ownership; net inventory by role is NOT identifiable and is not drawn.', 'Series recomputed from side × quantity per fill (independent of lineage); cumulative opened/closed = M2-B OA/CP totals.'),
        ('V2_position_lifecycle_timeline', 'V2 Position lifecycle timeline', 'One row per position episode: creation, adds, PARTIAL reductions (hollow marker: position remains), closure (square), reversal (diamond), expired-unclosed (none exists). Filter to any episode with `m2e_charts.py --episode=<id>`.', 'OBSERVED. A partial reduction is never drawn as a closure; a reversal is drawn as closure + successor episode.', 'Event counts equal the M2-B lifecycle table; closure events have inventory 0, partial reductions do not.'),
        ('V3_opening_activity_cohort_map', 'V3 Opening activity / cohort map', 'Opening items (parent order × instrument) by first-fill time and strike, CE and PE separately; units per ORDER-ENTRY MINUTE (the observed cohort key); TP-03 entry windows on a SEPARATE strip.', 'OBSERVED items; role = module-tag label. TP-03 window attribution is external and not a grouping of these items. No gap clustering is applied to openings.', 'Item quantities sum to the M2-B opening units; cohort-minute units sum to the same total.'),
        ('V4_C1_closing_batches', 'V4 Closing batches C1 (first-fill gap)', '10 s primary batches (time, size, duration), sensitivity 2/5/10/30/60 s, longest chains at 60 s vs 10 s, members and portions in the data files.', 'OBSERVATION of temporal clustering; a batch is a time-connected closing-order cluster, NEVER a decision.', 'Rows = committed M2-C batches for the cycle; member quantities sum to batch totals; batch closing units sum to the cycle closing units.'),
        ('V4_C2_closing_batches', 'V4 Closing batches C2 (last-to-first gap)', 'Same as C1 under the C2 rule; a separate view, never summed with C1.', 'As C1.', 'As C1.'),
        ('V5_W1_wing_body', 'V5 Wing/body W1', 'Candidate multiplicity, matched/unmatched units, link time offsets. Hatched = WEAKLY_SUPPORTED inferred candidate.', 'W1 = WEAKLY_SUPPORTED (same underlying, expiry, right, order-entry minute). Not ownership.', 'Observed wing/body unit totals equal M2-D items; candidate counts equal M2-D links.'),
        ('V5_W1_S60_wing_body', 'V5 Wing/body W1_S60', 'As W1 under ±60 s first-fill proximity (same IST session). Pale fill + dotted edge = UNRESOLVED.', 'W1_S60 = UNRESOLVED (execution-time proximity, not decision-time evidence).', 'As W1.'),
        ('V5_W2_wing_body', 'V5 Wing/body W2', 'Body units vs the sum of weighted wing units (weights, never allocations).', 'W2 = WEAKLY_SUPPORTED weights; no allocation or ownership meaning.', 'Weights taken from committed M2-D W2 links.'),
        ('V5_W3_wing_body', 'V5 Wing/body W3', 'Opening-level FIFO queue arithmetic: queue-matched units and residuals, per-link matched units.', 'W3 = UNRESOLVED; queue arithmetic, not ownership.', 'Matched + residual = observed totals; residual equals the M2-D W3 residual.'),
        ('V6_coverage_uncertainty_dashboard', 'V6 Coverage / uncertainty dashboard', 'Matched/unmatched wing and body units, multiplicity, closing-role exclusions, unclassified quantities, missing metadata, unresolved relationships, W1 vs W1_S60 disagreements, C1/C2 batch-count sensitivity, full-ledger scope numbers.', 'Mandatory; shows what is NOT known. Nothing is upgraded.', 'Values re-derived from the same datasets; full-ledger numbers taken from `m2d_summary.json`.')]
L = ['# M2-E — Visualization catalog', '', 'Generated by `tools/m2e_catalog.py` from `reports/m2e_figures/<cycle>/figure_manifest.json`. Every figure is drawn **only** from files in `reports/m2e_data/<cycle>/` and writes the plotted values to a sibling CSV (data-to-chart link). All times are IST (UTC+05:30). Historical marks are missing (source absent): no mark, no interpolated price, no unrealized P&L appears anywhere.', '',
     '## Visual language', '', '| Treatment | Meaning |', '|---|---|', '| Solid fill, solid outline | OBSERVED fact (fills, parents, lifecycle, unit totals, temporal clustering) |', '| Diagonal hatch | WEAKLY_SUPPORTED inferred candidate relation (W1, W2) |', '| Pale fill with dotted edge | UNRESOLVED (W1_S60, W3) |', '| Grey | unmatched / unclassified / excluded |', '| Red scope-warning footer | required full-ledger scope warnings (V3–V6) |', '',
     '## Figures', '']
for vid, name, what, ev, rec in DESC:
    L += [f'### {name} (`{vid}`)', '', f'* **Shows:** {what}', f'* **Evidence status:** {ev}', f'* **Reconciliation:** {rec}', '', '| Cycle | PNG | Data file(s) | Rows | Scope warning on figure |', '|---|---|---|---:|---|']
    for k in K:
        f = M[k][vid]; extra = ''.join(f"; `{os.path.basename(a['data_csv'])}` ({a['rows']})" for a in f['additional_data_csv'])
        L.append(f"| {k} | `{f['png'].replace('reports/', '')}` | `{os.path.basename(f['data_csv'])}` ({f['data_rows']}){extra} | {f['data_rows']} | {'yes' if f['scope_warning_shown'] else 'no (V1/V2 carry no wing/body claims)'} |")
    L.append('')
L += ['### Single-episode case charts (V2 filtered)', '', '| Cycle | Case | Episode(s) | PNG | Data |', '|---|---|---|---|---|']
for k in K:
    for f in CM[k]: L.append(f"| {k} | {f['case_type']} | {f['episodes']} | `{f['png'].replace('reports/', '')}` | `{os.path.basename(f['data_csv'])}` ({f['data_rows']}) |")
L += ['', '## Manifests', '', '* `reports/m2e_figures/<cycle>/figure_manifest.json` and `case_figure_manifest.json`: for each figure the PNG, the data CSV(s) with sha256 and row counts, and the source datasets (`reports/m2e_data/<cycle>/…`). PNG hashes are informational (renderer-dependent); CSV hashes are the reproducibility anchor.', '* `reports/m2e_data/<cycle>/manifest.json`: sha256 of every assembled dataset.', '', '## Scope warnings (displayed on V3–V6; numbers read from `m2d_summary.json`, not typed)', '']
sys.path.insert(0, os.path.join(PE, 'tools')); import importlib; CH = importlib.import_module('m2e_charts'); L += ['> ' + CH.SCOPE_WARNING, '', 'Evidence classes (never upgraded): W1 WEAKLY_SUPPORTED · W1_S60 UNRESOLVED · W3 UNRESOLVED · lot-level ownership and protective intent UNRESOLVED / NOT_TESTABLE.']
open(os.path.join(PE, 'reports', 'M2E_VISUALIZATION_CATALOG.md'), 'w').write('\n'.join(L) + '\n'); print(len(L), 'lines')
